def extract_bib_field(entry_text, field_name):
    """Extract a bib field value, handling nested braces correctly."""
    pattern = rf'{field_name}\s*=\s*\{{'
    m = re.search(pattern, entry_text, re.IGNORECASE)
    if not m:
        return ''
    start = m.end() - 1  # point at the opening {
    depth = 0
    i = start
    while i < len(entry_text):
        if entry_text[i] == '{':
            depth += 1
        elif entry_text[i] == '}':
            depth -= 1
            if depth == 0:
                return entry_text[start + 1:i]
        i += 1
    return ''


