# Check: every English line should be followed by a % Chinese line
# Find English lines NOT followed by % Chinese comment
awk '
/^%/ { next }
/^\\begin|^\\end|^\\maketitle|^\\title|^\\label|^\\centering|^\\caption|^\\Description|^\\includegraphics|^\\resizebox|^\\input|^\\toprule|^\\midrule|^\\bottomrule|^\\bibliograph|^\\newcommand|^\\setcopy|^\\settop|^\\renewcommand|^\\pagestyle|^\\usepackage|^\\pgfplots|^\\usetikz|^\\documentclass|^\\section|^\\subsection|^\\paragraph|^%%|^$/ { next }
/^[A-Z\\]/ {
  line = NR; content = $0
  getline nextline
  if (nextline !~ /^%/) {
    print line": MISSING Chinese: "substr(content, 1, 80)
  }
}
' main.tex | head -30

# More precise: count lines that have English content but the NEXT non-empty line is not a % comment
# Focus on sections that were rewritten
awk '
/^%/ {next}
/^$/ {next}
/^\\begin|^\\end|^\\maketitle|^\\documentclass|^\\setcopy|^\\settop|^\\renewcommand|^\\pagestyle|^\\usepackage|^\\pgfplots|^\\usetikz|^\\newcommand|^\\toprule|^\\midrule|^\\bottomrule/ {next}
{prev_line = NR; prev_content = $0}
' main.tex > /dev/null

# Simpler: count % comment lines vs non-comment non-empty lines in body
echo "English lines (non-comment, non-empty, non-markup):"
grep -v '^%' main.tex | grep -v '^$' | grep -v '^\\\\begin\|^\\\\end\|^\\\\make\|^\\\\title\|^\\\\label\|^\\\\centering\|^\\\\caption\|^\\\\Description\|^\\\\include\|^\\\\resize\|^\\\\input\|^\\\\toprule\|^\\\\midrule\|^\\\\bottomrule\|^\\\\biblio\|^\\\\newcommand\|^\\\\setcopy\|^\\\\settop\|^\\\\renewcommand\|^\\\\pagestyle\|^\\\\usepackage\|^\\\\pgfplots\|^\\\\usetikz\|^\\\\documentclass\|^%%' | wc -l
echo "Chinese comment lines:"
grep -c '^%' main.tex

# Find sentences (lines ending with . or }) that are NOT followed by a % comment within 3 lines
awk '
/\.$/ || /\}$/ {
  eng_line = NR; eng = $0
  found_zh = 0
  for (i = 1; i <= 3; i++) {
    if (getline > 0 && $0 ~ /^%/) { found_zh = 1; break }
    if ($0 ~ /^$/) continue
    break
  }
  if (!found_zh && eng !~ /^%/ && eng !~ /^\\begin|^\\end|^\\toprule|^\\midrule|^\\bottomrule|^\\label|^\\Description/) {
    print eng_line": "substr(eng, 1, 80)
  }
}
' main.tex | grep -v '\\\\$' | tail -30

